<?php
class Reporte_formas_pago extends CI_Controller{
 private $session_data=array();
 public function __construct(){parent::__construct();if(!$this->session->userdata('logged_in'))redirect('','refresh');$this->session_data=$this->session->userdata('logged_in');$this->load->model('Reporte_formas_pago_model');$this->load->model('Sistema_model');$this->load->model('Parametro_model');if(!$this->Reporte_formas_pago_model->usuario_tiene_rol((int)$this->session_data['usuario_id'],220))show_error('No tiene permiso para generar reportes de Transporte.',403,'Acceso denegado');}
 private function filtros(){ $d=trim((string)$this->input->get('desde',true));$h=trim((string)$this->input->get('hasta',true));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$d))$d=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$h))$h=date('Y-m-d');if($d>$h){$x=$d;$d=$h;$h=$x;}return array('desde'=>$d,'hasta'=>$h,'caja_id'=>(int)$this->input->get('caja_id',true),'usuario_id'=>(int)$this->input->get('usuario_id',true));}
 public function index(){ $f=$this->filtros();$p=$this->Parametro_model->get_parametros();$data['sistema']=$this->Sistema_model->get_sistema();$data['parametro']=isset($p[0])?$p[0]:$p;$data['filtros']=$f;$data['listas']=$this->Reporte_formas_pago_model->listas();$data['filas']=$this->Reporte_formas_pago_model->resumen($f);$data['control']=$this->Reporte_formas_pago_model->control($f);$data['page_title']='Reporte de formas de pago';$data['_view']='reporte_transporte/formas_pago';$this->load->view('layouts/main',$data);}
 public function csv(){ $f=$this->filtros();$rs=$this->Reporte_formas_pago_model->resumen($f);header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="formas_pago_'.$f['desde'].'_'.$f['hasta'].'.csv"');echo "\xEF\xBB\xBF";$x=fopen('php://output','w');fputcsv($x,array('Forma de pago','Operaciones','Total'),';');foreach($rs as $r)fputcsv($x,array($r['forma'],$r['operaciones'],$r['total']),';');fclose($x);exit;}
}
